import os
from xml.sax.saxutils import escape, quoteattr

from pyspark.sql import functions as F


def tag(name, value):
    return "" if value is None else f"<{name}>{escape(str(value))}</{name}>"


def attr(name, value):
    return "" if value is None else f" {name}={quoteattr(value)}"


def export(suppliers, path):
    """The partner's file, written for you: one <supplier> element per supplier."""
    rows = []
    for r in suppliers.collect():
        rows.append(
            f"  <supplier{attr('id', r['supplier_id'])}{attr('system', r['source_system'])}>"
            f"{tag('name', r['supplier_name'])}{tag('country', r['country'])}"
            f"<terms>{tag('days', r['payment_terms_days'])}</terms>"
            f"<contact>{tag('email', r['contact_email'])}</contact></supplier>"
        )
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w") as f:
        f.write("<suppliers>\n" + "\n".join(rows) + "\n</suppliers>\n")


def load(path):
    # Read the partner's XML at `path` and return a flat suppliers table.
    pass


def solve(suppliers):
    path = "/tmp/partner/suppliers.xml"
    export(suppliers, path)
    return load(path)
